schemas.schema-01-systematic.prisma:
/// Application-level configuration entries scoped by environment. Stores
/// atomic key-value pairs that influence platform behavior (e.g.,
/// thresholds, toggles) without denormalized or computed data. Authorship
/// and maintenance are performed by {@link pol_econ_board_admins}. Each
/// (environment, key) combination is unique. Search on description supports
/// operator-facing discovery.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_econ_board_app_settings {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Authoring administrator's {@link pol_econ_board_admins.id}
  created_by_admin_id String @db.Uuid

  /// Last updating administrator's {@link pol_econ_board_admins.id}
  updated_by_admin_id String? @db.Uuid

  /// Logical environment for the setting. Examples: "production", "staging",
  /// "development". Used to scope configuration safely by deployment context.
  environment String

  /// Business identifier for the configuration setting. Must be unique within
  /// the same environment.
  key String

  /// Raw setting value in string form. Interpretation is application-defined;
  /// no computed or derived values are stored here.
  value String

  /// Optional grouping for operators (e.g., "auth", "governance",
  /// "notifications").
  category String?

  /// Human-readable explanation of the setting's purpose and acceptable values.
  description String?

  /// Whether this setting is currently active in the specified environment.
  active Boolean

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp when setting is retired.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  created_by_admin pol_econ_board_admins @relation("pol_econ_board_app_settings_of_created_by_admin_id", fields: [created_by_admin_id], references: [id], onDelete: Cascade)
  updated_by_admin pol_econ_board_admins? @relation("pol_econ_board_app_settings_of_updated_by_admin_id", fields: [updated_by_admin_id], references: [id], onDelete: Cascade)

  @@index([created_by_admin_id])
  @@index([updated_by_admin_id])

  @@unique([environment, key])
  @@index([active, environment])
  @@index([created_at])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Feature flag definitions controlling conditional behavior by environment
/// with optional rollout strategies. Supports time-bounded activation and
/// percentage rollouts. Managed by administrators in {@link
/// pol_econ_board_admins}. Uniqueness enforced per (environment, name).
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_econ_board_feature_flags {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Authoring administrator's {@link pol_econ_board_admins.id}
  created_by_admin_id String @db.Uuid

  /// Last updating administrator's {@link pol_econ_board_admins.id}
  updated_by_admin_id String? @db.Uuid

  /// Environment scope for the flag. Examples: "production", "staging",
  /// "development".
  environment String

  /// Feature flag name unique within the same environment.
  name String

  /// Operator-facing description of what this flag controls.
  description String?

  /// Whether the flag is currently enabled (subject to time windows and
  /// strategy).
  enabled Boolean

  /// Strategy keyword indicating how the flag is rolled out. Examples: "all",
  /// "percentage", "role_based".
  rollout_strategy String

  /// Optional percentage (0–100) when rollout_strategy is "percentage".
  rollout_percentage Int? @db.Integer

  /// Optional activation start time. When null, active immediately if enabled.
  starts_at DateTime? @db.Timestamptz

  /// Optional activation end time. When null, no scheduled end.
  ends_at DateTime? @db.Timestamptz

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp when retired.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  created_by_admin pol_econ_board_admins @relation("pol_econ_board_feature_flags_of_created_by_admin_id", fields: [created_by_admin_id], references: [id], onDelete: Cascade)
  updated_by_admin pol_econ_board_admins? @relation("pol_econ_board_feature_flags_of_updated_by_admin_id", fields: [updated_by_admin_id], references: [id], onDelete: Cascade)

  @@index([created_by_admin_id])
  @@index([updated_by_admin_id])

  @@unique([environment, name])
  @@index([environment, enabled, starts_at, ends_at], map: "pol_econ_board_feature_flags_environment_enabled_start_f458528d")
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Planned or active maintenance windows defining service impact scope and
/// tier. Prevents duplication via unique codes and unique (scope, starts_at,
/// ends_at). Authored/approved by {@link pol_econ_board_admins}. Optimized
/// for time-range queries and operator search.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
