  /// Authoring administrator's {@link pol_econ_board_admins.id}
  created_by_admin_id String @db.Uuid

  /// Approving administrator's {@link pol_econ_board_admins.id} when required
  /// by policy.
  approved_by_admin_id String? @db.Uuid

  /// Unique business identifier for the maintenance window.
  code String

  /// Human-readable title of the maintenance window.
  title String

  /// Detailed description of scope, steps, and risk notes.
  description String?

  /// Business scope affected (e.g., "all", "auth", "feeds").
  scope String

  /// Impact tier label (e.g., "P0", "P1", "P2").
  impact_tier String

  /// Lifecycle state such as "planned", "in_progress", "completed", or
  /// "canceled".
  status String

  /// Start timestamp of the maintenance window.
  starts_at DateTime @db.Timestamptz

  /// End timestamp of the maintenance window.
  ends_at DateTime @db.Timestamptz

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp when retired.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  created_by_admin pol_econ_board_admins @relation("pol_econ_board_maintenance_windows_of_created_by_admin_id", fields: [created_by_admin_id], references: [id], onDelete: Cascade)
  approved_by_admin pol_econ_board_admins? @relation("pol_econ_board_maintenance_windows_of_approved_by_admin_id", fields: [approved_by_admin_id], references: [id], onDelete: Cascade)

  @@index([created_by_admin_id])
  @@index([approved_by_admin_id])

  @@unique([code])
  @@unique([scope, starts_at, ends_at])
  @@index([starts_at, ends_at])
  @@index([impact_tier, starts_at])
  @@index([scope, status, starts_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

