schemas.schema-06-personalization.prisma:
/// User-owned bookmark collections providing organization for bookmarks.
/// Each collection belongs to an account ({@link pol_econ_board_accounts})
/// and can be referenced by many {@link pol_econ_board_bookmarks}. Names are
/// unique per owner to avoid duplicates. Text search over names is supported
/// via GIN. Soft delete is supported for reversible removal.
///
/// @namespace Personalization
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_econ_board_bookmark_collections {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owner account's {@link pol_econ_board_accounts.id}
  pol_econ_board_account_id String @db.Uuid

  /// Human-readable collection name. Unique per account for easier selection.
  name String

  /// Optional description to explain the collection’s purpose to the owner.
  description String?

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp, if the collection is removed but retained for
  /// recovery.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  bookmark_collection_account pol_econ_board_accounts @relation(fields: [pol_econ_board_account_id], references: [id], onDelete: Cascade, map: "pol_econ_board_bookmark_collections_pol_econ_board_acc_627e0f66")

  pol_econ_board_bookmarks pol_econ_board_bookmarks[]

  @@unique([pol_econ_board_account_id, name], map: "pol_econ_board_bookmark_collections_pol_econ_board_acc_df35346f")
  @@index([pol_econ_board_account_id, created_at], map: "pol_econ_board_bookmark_collections_pol_econ_board_acc_2d2a198f")
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Per-user bookmarks for posts. Each bookmark belongs to an account ({@link
/// pol_econ_board_accounts}) and targets a post ({@link
/// pol_econ_board_posts}). Optionally associated with a {@link
/// pol_econ_board_bookmark_collections} folder. No post data is
/// denormalized; business logic computes display from joins.
///
/// @namespace Personalization
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_econ_board_bookmarks {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Bookmark owner account's {@link pol_econ_board_accounts.id}
  pol_econ_board_account_id String @db.Uuid

  /// Target post's {@link pol_econ_board_posts.id}
  pol_econ_board_post_id String @db.Uuid

  /// Optional collection's {@link pol_econ_board_bookmark_collections.id} for
  /// foldering.
  pol_econ_board_bookmark_collection_id String? @db.Uuid

  /// Optional personal note about the bookmark for the owner only.
  note String?

  /// Creation timestamp when the bookmark was added.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp (e.g., note or collection change).
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp when the bookmark is removed but retained for
  /// recovery.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  bookmark_account pol_econ_board_accounts @relation(fields: [pol_econ_board_account_id], references: [id], onDelete: Cascade)
  bookmark_post pol_econ_board_posts @relation(fields: [pol_econ_board_post_id], references: [id], onDelete: Cascade)
  bookmark_collection pol_econ_board_bookmark_collections? @relation(fields: [pol_econ_board_bookmark_collection_id], references: [id], onDelete: Cascade, map: "pol_econ_board_bookmarks_pol_econ_board_bookmark_colle_c27bece7")

  @@index([pol_econ_board_post_id])

  @@unique([pol_econ_board_account_id, pol_econ_board_post_id], map: "pol_econ_board_bookmarks_pol_econ_board_account_id_pol_f6353644")
  @@index([pol_econ_board_account_id, created_at], map: "pol_econ_board_bookmarks_pol_econ_board_account_id_cre_6eda6673")
  @@index([pol_econ_board_bookmark_collection_id, created_at], map: "pol_econ_board_bookmarks_pol_econ_board_bookmark_colle_daf08ae0")
  @@index([note(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Per-user reading telemetry for posts. Tracks first view, progress
/// percentage, and dwell seconds for a post. Belongs to an account ({@link
/// pol_econ_board_accounts}) and a post ({@link pol_econ_board_posts}).
/// Enforces one record per (user, post) to maintain a canonical source of
/// progress.
///
/// @namespace Personalization
