  /// Target post's {@link pol_econ_board_posts.id}
  pol_econ_board_post_id String @db.Uuid

  /// Timestamp when the user first viewed the post.
  first_viewed_at DateTime? @db.Timestamptz

  /// Latest known reading progress percentage (0–100).
  progress_percent Int @db.Integer

  /// Cumulative engaged seconds measured by the application for the post.
  dwell_seconds Int? @db.Integer

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp, if the state is purged logically.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  read_state_account pol_econ_board_accounts @relation(fields: [pol_econ_board_account_id], references: [id], onDelete: Cascade)
  read_state_post pol_econ_board_posts @relation(fields: [pol_econ_board_post_id], references: [id], onDelete: Cascade)

  @@unique([pol_econ_board_account_id, pol_econ_board_post_id], map: "pol_econ_board_read_states_pol_econ_board_account_id_p_5d3390ed")
  @@index([pol_econ_board_account_id, updated_at], map: "pol_econ_board_read_states_pol_econ_board_account_id_u_afeee45b")
  @@index([pol_econ_board_post_id, updated_at], map: "pol_econ_board_read_states_pol_econ_board_post_id_upda_f9abfb95")
}

/// Unified follows table allowing a user to follow either an author
