/// Application-level configuration entries scoped by environment. Stores
/// atomic key-value pairs that influence platform behavior (e.g.,
/// thresholds, toggles) without denormalized or computed data. Authorship
/// and maintenance are performed by {@link pol_econ_board_admins}. Each
/// (environment, key) combination is unique. Search on description supports
/// operator-facing discovery.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_econ_board_app_settings {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Authoring administrator's {@link pol_econ_board_admins.id}
  created_by_admin_id String @db.Uuid

  /// Last updating administrator's {@link pol_econ_board_admins.id}
  updated_by_admin_id String? @db.Uuid

  /// Logical environment for the setting. Examples: "production", "staging",
  /// "development". Used to scope configuration safely by deployment context.
  environment String

  /// Business identifier for the configuration setting. Must be unique within
  /// the same environment.
  key String

  /// Raw setting value in string form. Interpretation is application-defined;
  /// no computed or derived values are stored here.
  value String

  /// Optional grouping for operators (e.g., "auth", "governance",
  /// "notifications").
  category String?

  /// Human-readable explanation of the setting's purpose and acceptable values.
  description String?

  /// Whether this setting is currently active in the specified environment.
  active Boolean

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp when setting is retired.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  created_by_admin pol_econ_board_admins  @relation("pol_econ_board_app_settings_of_created_by_admin_id", fields: [created_by_admin_id], references: [id], onDelete: Cascade)
  updated_by_admin pol_econ_board_admins? @relation("pol_econ_board_app_settings_of_updated_by_admin_id", fields: [updated_by_admin_id], references: [id], onDelete: Cascade)

  @@unique([environment, key])
  @@index([created_by_admin_id])
  @@index([updated_by_admin_id])
  @@index([active, environment])
  @@index([created_at])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

