  @@index([category, created_at])
  @@index([pol_econ_board_account_id, created_at], map: "pol_econ_board_audit_logs_pol_econ_board_account_id_cr_69f116b0")
  @@index([resource_type, created_at])
  @@index([resource_type, resource_id, created_at], map: "pol_econ_board_audit_logs_resource_type_resource_id_cr_822365cb")
  @@index([action(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-03-curation.prisma:
/// Editorial taxonomy categories for organizing posts. Supports hierarchical
/// structures via optional self-referencing parent. Typically curated by
/// editors. Uniqueness is enforced through slugs and optionally names to
/// prevent duplicates across taxonomy. Related entities: {@link
/// pol_econ_board_posts} through categorization features and {@link
/// pol_econ_board_tags} where taxonomy intersects with tagging. Parent
/// onDelete is SetNull to avoid accidental subtree deletions.
///
/// @namespace Curation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_econ_board_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent category's {@link pol_econ_board_categories.id}. Enables
  /// hierarchical taxonomy. SetNull on delete to preserve children.
  parent_id String? @db.Uuid

  /// Owning editor's {@link pol_econ_board_editors.id}. Indicates editorial
  /// ownership/creator.
  pol_econ_board_editor_id String? @db.Uuid

  /// Human-readable category name used in UI and listings.
  name String

  /// URL-friendly unique identifier for the category used in routing and
  /// lookups.
  slug String

  /// Optional descriptive text providing context for the category.
  description String?

  /// Whether the category is active for new assignments and visibility.
  active Boolean

  /// Optional display ordering index for curated lists. Purely a presentation
  /// hint.
  order_index Int? @db.Integer

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp. Null when the category is active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  parent_category pol_econ_board_categories? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)
  owner_editor    pol_econ_board_editors?    @relation(fields: [pol_econ_board_editor_id], references: [id], onDelete: Cascade)

  recursive                       pol_econ_board_categories[]       @relation("recursive")
  pol_econ_board_pinned_posts     pol_econ_board_pinned_posts[]
  pol_econ_board_taxonomy_changes pol_econ_board_taxonomy_changes[]
  pol_econ_board_posts            pol_econ_board_posts[]
  pol_econ_board_post_versions    pol_econ_board_post_versions[]
  pol_econ_board_follows          pol_econ_board_follows[]
  pol_econ_board_muted_sources    pol_econ_board_muted_sources[]

  @@unique([slug])
  @@unique([name])
  @@index([parent_id, created_at])
  @@index([pol_econ_board_editor_id, created_at], map: "pol_econ_board_categories_pol_econ_board_editor_id_cre_32b4955d")
  @@index([created_at])
}

/// Editorial tags used to label posts for discovery and personalization.
/// Managed by editors, independent from hierarchical categories. Uniqueness
/// enforced via slug and name. Related through {@link
/// pol_econ_board_post_tags} to {@link pol_econ_board_posts}.
///
/// @namespace Curation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_econ_board_tags {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owning editor's {@link pol_econ_board_editors.id}. Indicates who
  /// created/manages this tag.
  pol_econ_board_editor_id String? @db.Uuid

  /// Human-readable tag name. Used in search and UI.
  name String

  /// URL-friendly unique identifier for the tag used in routing and lookups.
  slug String

  /// Optional explanatory description for editorial context.
  description String?

  /// Whether the tag is available for assignment and discovery.
  active Boolean

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp. Null when active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  tag_owner_editor pol_econ_board_editors? @relation(fields: [pol_econ_board_editor_id], references: [id], onDelete: Cascade)

  pol_econ_board_post_tags        pol_econ_board_post_tags[]
  pol_econ_board_taxonomy_changes pol_econ_board_taxonomy_changes[]
  pol_econ_board_follows          pol_econ_board_follows[]
  pol_econ_board_muted_sources    pol_econ_board_muted_sources[]

  @@unique([slug])
  @@unique([name])
  @@index([pol_econ_board_editor_id, created_at])
  @@index([created_at])
}

/// Junction table connecting posts and tags to implement M:N relationships.
/// Each row records a tag assignment to a post with audit timestamps.
/// Prevents duplicate assignments via composite unique constraint. Related
/// entities: {@link pol_econ_board_posts}, {@link pol_econ_board_tags}.
///
/// @namespace Curation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_econ_board_post_tags {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Target post's {@link pol_econ_board_posts.id}.
