  /// Last update timestamp for this assignment record.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp if the assignment is removed.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  tag_post pol_econ_board_posts @relation(fields: [pol_econ_board_post_id], references: [id], onDelete: Cascade)
  post_tag pol_econ_board_tags  @relation(fields: [pol_econ_board_tag_id], references: [id], onDelete: Cascade)

  @@unique([pol_econ_board_post_id, pol_econ_board_tag_id], map: "pol_econ_board_post_tags_pol_econ_board_post_id_pol_ec_e6d2fa43")
  @@index([pol_econ_board_post_id, created_at])
  @@index([pol_econ_board_tag_id, created_at])
}

/// Editor-owned curated collections used to feature or package posts (e.g.,
