  //----
  // RELATIONS
  //----
  collection_item_owner  pol_econ_board_curated_collections @relation(fields: [pol_econ_board_curated_collection_id], references: [id], onDelete: Cascade, map: "pol_econ_board_collection_items_pol_econ_board_curated_d2d3f9a3")
  collection_item_post   pol_econ_board_posts               @relation(fields: [pol_econ_board_post_id], references: [id], onDelete: Cascade)
