  @@unique([pol_econ_board_curated_collection_id, pol_econ_board_post_id], map: "pol_econ_board_collection_items_pol_econ_board_curated_635f9984")
  @@unique([pol_econ_board_curated_collection_id, position], map: "pol_econ_board_collection_items_pol_econ_board_curated_c020c8f3")
  @@index([pol_econ_board_editor_id])
  @@index([pol_econ_board_curated_collection_id, created_at], map: "pol_econ_board_collection_items_pol_econ_board_curated_d68174d7")
  @@index([pol_econ_board_post_id, created_at], map: "pol_econ_board_collection_items_pol_econ_board_post_id_40051cd2")
}

/// Editorial pin records for elevating posts in specific scopes (e.g., home,
/// section/category). Tracks who pinned, optional category scoping,
/// expiration, and reasons. Enforces uniqueness per (post, scope) to avoid
/// duplicate pins in the same context. Related to {@link
/// pol_econ_board_posts}, {@link pol_econ_board_categories}, and {@link
/// pol_econ_board_editors}. Adds a composite index for common retrieval by
/// scope/category with priority.
