  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Pinned post's {@link pol_econ_board_posts.id}.
  pol_econ_board_post_id String @db.Uuid

  /// Editor who performed the pin action {@link pol_econ_board_editors.id}.
  pol_econ_board_editor_id String @db.Uuid

  /// Optional category scope {@link pol_econ_board_categories.id} if the pin
