  pol_econ_board_category_id String? @db.Uuid

  /// Editorial scope for the pin (e.g., home, section, topic identifier).
  scope String

  /// Optional reason or note explaining the pin decision.
  reason String?

  /// Optional expiration for the pin after which it should no longer be
