  @@unique([pol_econ_board_post_id, scope])
  @@index([pol_econ_board_editor_id])
  @@index([pol_econ_board_category_id, created_at], map: "pol_econ_board_pinned_posts_pol_econ_board_category_id_dcb7b48e")
  @@index([expires_at, created_at])
  @@index([scope, pol_econ_board_category_id, priority], map: "pol_econ_board_pinned_posts_scope_pol_econ_board_categ_b9ce0568")
}

/// Editorial announcements and service notices authored by editors/admins
