  @@index([pol_econ_board_comment_id, pol_econ_board_reaction_type_id], map: "pol_econ_board_reactions_pol_econ_board_comment_id_pol_d438938c")
}

/// Catalog of allowable vote choices for the platform (e.g., "Agree",
