  followed_pol_econ_board_account_id String? @db.Uuid

  /// Followed tag's {@link pol_econ_board_tags.id} (nullable unless following
  /// a tag).
  pol_econ_board_tag_id String? @db.Uuid

  /// Followed category's {@link pol_econ_board_categories.id} (nullable unless
  /// following a category).
  pol_econ_board_category_id String? @db.Uuid

  /// Follow creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp if the follow is removed logically.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  follow_follower_account pol_econ_board_accounts    @relation("pol_econ_board_follows_of_follower_pol_econ_board_account_id", fields: [follower_pol_econ_board_account_id], references: [id], onDelete: Cascade)
  follow_followed_account pol_econ_board_accounts?   @relation("pol_econ_board_follows_of_followed_pol_econ_board_account_id", fields: [followed_pol_econ_board_account_id], references: [id], onDelete: Cascade)
  follow_tag              pol_econ_board_tags?       @relation(fields: [pol_econ_board_tag_id], references: [id], onDelete: Cascade)
  follow_category         pol_econ_board_categories? @relation(fields: [pol_econ_board_category_id], references: [id], onDelete: Cascade)

  @@unique([follower_pol_econ_board_account_id, followed_pol_econ_board_account_id], map: "pol_econ_board_follows_follower_pol_econ_board_account_c74076ec")
  @@unique([follower_pol_econ_board_account_id, pol_econ_board_tag_id], map: "pol_econ_board_follows_follower_pol_econ_board_account_2c84af2c")
  @@unique([follower_pol_econ_board_account_id, pol_econ_board_category_id], map: "pol_econ_board_follows_follower_pol_econ_board_account_c4992592")
  @@index([followed_pol_econ_board_account_id])
  @@index([pol_econ_board_tag_id])
  @@index([pol_econ_board_category_id])
  @@index([follower_pol_econ_board_account_id, created_at], map: "pol_econ_board_follows_follower_pol_econ_board_account_4f9f5d5d")
}

/// Per-account feed preference profile controlling default sort and
