  @@index([pol_econ_board_post_id])
  @@index([pol_econ_board_account_id, saved_at], map: "pol_econ_board_saved_items_pol_econ_board_account_id_s_1545a8ea")
  @@index([snapshot_title(ops: raw("gin_trgm_ops"))], type: Gin)
