schemas.schema-07-moderation.prisma:
/// Individual user reports against content (post or comment). Stores
/// reporter, target reference, reason code, and optional notes at submission
/// time. Links to reporter tier snapshot for weighting without embedding
/// business logic. FKs to target content use SetNull to preserve evidence on
/// content deletion; taxonomy FKs (reason codes) use NoAction.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_econ_board_reports {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reporter account's {@link pol_econ_board_accounts.id}
  reporter_account_id String @db.Uuid

  /// Reported post's {@link pol_econ_board_posts.id} (nullable when the target
  /// is a comment).
  post_id String? @db.Uuid

  /// Reported comment's {@link pol_econ_board_comments.id} (nullable when the
  /// target is a post).
  comment_id String? @db.Uuid

  /// Reason taxonomy reference {@link pol_econ_board_reason_codes.id}.
  reason_code_id String @db.Uuid

  /// Reporter tier snapshot at submission {@link
  /// pol_econ_board_reporter_tiers.id}.
  reporter_tier_id String? @db.Uuid

  /// Optional free-text notes from the reporter to give context to reviewers.
  notes String?

  /// Captured weight at submission time (e.g., credibility weighting). Not
  /// calculated by DB; recorded as received.
  weight Float? @db.DoublePrecision

  /// Creation timestamp (report submitted at).
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for this report record.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp, if the report is retracted or purged under
  /// policy.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  reporter_account pol_econ_board_accounts        @relation(fields: [reporter_account_id], references: [id], onDelete: Cascade)
  post             pol_econ_board_posts?          @relation(fields: [post_id], references: [id], onDelete: Cascade)
  comment          pol_econ_board_comments?       @relation(fields: [comment_id], references: [id], onDelete: Cascade)
  reason_code      pol_econ_board_reason_codes    @relation(fields: [reason_code_id], references: [id], onDelete: Cascade)
  reporter_tier    pol_econ_board_reporter_tiers? @relation(fields: [reporter_tier_id], references: [id], onDelete: Cascade)

  pol_econ_board_moderation_cases pol_econ_board_moderation_cases?

  @@index([reporter_account_id, created_at])
  @@index([post_id, created_at])
  @@index([comment_id, created_at])
  @@index([reason_code_id])
  @@index([reporter_tier_id])
  @@index([notes(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Moderation case container aggregating related reports and tracking
/// lifecycle (status, SLA, assignment). Actions and sanctions are recorded
/// in {@link pol_econ_board_moderation_actions} and {@link
/// pol_econ_board_sanctions}. Assignment now references {@link
/// pol_econ_board_moderators} to enforce RBAC. The initial report link is
/// nullable and preserved on report deletion via SetNull.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_econ_board_moderation_cases {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Initial/seed report reference {@link pol_econ_board_reports.id}.
  initial_report_id String? @db.Uuid

  /// Assigned moderator's {@link pol_econ_board_moderators.id}.
  pol_econ_board_moderator_id String? @db.Uuid

  /// Current case status (e.g., triage, under_review, action_applied, closed).
  status String

  /// Priority bucket used for queue ordering (lower is more urgent).
  priority Int? @db.Integer

  /// Optional case summary for human-readable context.
  summary String?

  /// Case opening timestamp.
  opened_at DateTime @db.Timestamptz

  /// Case closure timestamp if resolved.
  closed_at DateTime? @db.Timestamptz

  /// SLA due timestamp for first response or resolution per policy.
  sla_due_at DateTime? @db.Timestamptz

  /// Creation timestamp for the case record.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for the case record.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp if the case is obsoleted per policy.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  initial_report     pol_econ_board_reports?    @relation(fields: [initial_report_id], references: [id], onDelete: Cascade)
  assigned_moderator pol_econ_board_moderators? @relation(fields: [pol_econ_board_moderator_id], references: [id], onDelete: Cascade, map: "pol_econ_board_moderation_cases_pol_econ_board_moderat_ea3e0a09")

  pol_econ_board_moderation_actions pol_econ_board_moderation_actions[]
  pol_econ_board_sanctions          pol_econ_board_sanctions[]
  pol_econ_board_transparency_logs  pol_econ_board_transparency_logs[]
  pol_econ_board_appeals            pol_econ_board_appeals[]
  pol_econ_board_auto_hide_events   pol_econ_board_auto_hide_events[]
  pol_econ_board_content_labels     pol_econ_board_content_labels[]

  @@unique([initial_report_id])
  @@index([status, updated_at])
  @@index([pol_econ_board_moderator_id, updated_at], map: "pol_econ_board_moderation_cases_pol_econ_board_moderat_1582b821")
  @@index([summary(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Atomic actions/decisions taken during a moderation case with provenance
/// and optional reason code. Serves as the auditable action log for {@link
/// pol_econ_board_moderation_cases}.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_econ_board_moderation_actions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent case {@link pol_econ_board_moderation_cases.id}.
  moderation_case_id String @db.Uuid

  /// Action performer account {@link pol_econ_board_accounts.id}.
  actor_account_id String @db.Uuid

  /// Optional reason code for classification {@link
  /// pol_econ_board_reason_codes.id}.
  reason_code_id String? @db.Uuid

  /// Action type label (e.g., label, hide, remove, warn).
  action_type String

  /// Optional human rationale or notes supporting the action.
  rationale String?

  /// When the action takes effect (if deferred).
  effective_from DateTime? @db.Timestamptz

  /// When the action effect ends, if applicable.
  effective_to DateTime? @db.Timestamptz

  /// Creation timestamp for this action record.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for this action record.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for this action record.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  moderation_case pol_econ_board_moderation_cases @relation(fields: [moderation_case_id], references: [id], onDelete: Cascade)
  actor_account   pol_econ_board_accounts         @relation(fields: [actor_account_id], references: [id], onDelete: Cascade)
  reason_code     pol_econ_board_reason_codes?    @relation(fields: [reason_code_id], references: [id], onDelete: Cascade)

  @@index([reason_code_id])
  @@index([moderation_case_id, created_at], map: "pol_econ_board_moderation_actions_moderation_case_id_c_9ec34a49")
  @@index([actor_account_id, created_at], map: "pol_econ_board_moderation_actions_actor_account_id_cre_2a9c48f1")
  @@index([rationale(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Sanction outcomes applied to accounts as results of moderation cases.
/// Stores type, validity window, and active flag with provenance to {@link
/// pol_econ_board_moderation_cases}.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_econ_board_sanctions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Related moderation case {@link pol_econ_board_moderation_cases.id}.
  moderation_case_id String @db.Uuid

  /// Sanctioned subject account {@link pol_econ_board_accounts.id}.
  subject_account_id String @db.Uuid

  /// Decision maker account {@link pol_econ_board_accounts.id}.
  decided_by_account_id String @db.Uuid

  /// Optional reason code categorization {@link
  /// pol_econ_board_reason_codes.id}.
  reason_code_id String? @db.Uuid

  /// Sanction type (e.g., warning, feature_restriction, suspend_24h,
  /// suspend_7d, suspend_30d, permanent).
  sanction_type String

  /// Optional summary for transparency and internal review.
  reason_summary String?

  /// Whether the sanction is currently active within the validity window.
  active Boolean

  /// Sanction start timestamp.
  start_at DateTime @db.Timestamptz

  /// Sanction end timestamp if not permanent.
  end_at DateTime? @db.Timestamptz

  /// Creation timestamp for the sanction record.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for the sanction record.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for the sanction record.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  moderation_case    pol_econ_board_moderation_cases @relation(fields: [moderation_case_id], references: [id], onDelete: Cascade)
  subject_account    pol_econ_board_accounts         @relation("pol_econ_board_sanctions_of_subject_account_id", fields: [subject_account_id], references: [id], onDelete: Cascade)
  decided_by_account pol_econ_board_accounts         @relation("pol_econ_board_sanctions_of_decided_by_account_id", fields: [decided_by_account_id], references: [id], onDelete: Cascade)
  reason_code        pol_econ_board_reason_codes?    @relation(fields: [reason_code_id], references: [id], onDelete: Cascade)

  @@unique([moderation_case_id, sanction_type])
  @@index([decided_by_account_id])
  @@index([reason_code_id])
  @@index([subject_account_id, start_at])
  @@index([active, end_at])
  @@index([reason_summary(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Public transparency records summarizing moderation outcomes for cases,
