  @@index([published_by_account_id])
  @@index([published_at])
  @@index([moderation_case_id, published_at], map: "pol_econ_board_transparency_logs_moderation_case_id_pu_1f6d35b1")
  @@index([public_summary(ops: raw("gin_trgm_ops"))], type: Gin)
