/// Current consent state per account and communication category/channel with
/// optional scope granularity. Records provenance (source, evidence) and
/// locale/user-agent context. Immutable history is maintained in {@link
/// pol_econ_board_consent_logs}. The unique constraint includes scope to
/// enable separate consents per topic/campaign within the same
/// category×channel.
///
/// @namespace Compliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_econ_board_consents {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Subject account's {@link pol_econ_board_accounts.id}
  pol_econ_board_account_id String @db.Uuid

  /// Recording admin's {@link pol_econ_board_admins.id} (if staff recorded on
  /// behalf)
  pol_econ_board_admin_id String? @db.Uuid

  /// Consent category (e.g., marketing, engagement, digest).
  /// Business-controlled taxonomy.
  category String

  /// Communication channel (e.g., in_app, email). Business-controlled taxonomy.
  channel String

  /// Optional consent scope qualifier (e.g., specific topic, campaign, or
  /// series) enabling granular consent distinctions under the same
  /// category×channel.
  scope String

  /// Whether consent is granted (true) or declined/withdrawn (false).
  granted Boolean

  /// When this consent state became effective.
  granted_at DateTime @db.Timestamptz

  /// When consent was withdrawn (if applicable).
  revoked_at DateTime? @db.Timestamptz

  /// Source of consent: signup, preferences_page, campaign, etc.
  source String

  /// URI reference to evidence (e.g., message copy, signed form).
  evidence_uri String? @db.VarChar(80000)

  /// User agent string captured at consent time, if available.
  user_agent String?

  /// Locale used when consent was captured (e.g., en-US, ko-KR).
  locale String?

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Record last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp, if the consent record is deprecated.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  account         pol_econ_board_accounts @relation(fields: [pol_econ_board_account_id], references: [id], onDelete: Cascade)
  recording_admin pol_econ_board_admins?  @relation(fields: [pol_econ_board_admin_id], references: [id], onDelete: Cascade)

  pol_econ_board_consent_logs pol_econ_board_consent_logs[]

  @@unique([pol_econ_board_account_id, category, channel, scope], map: "pol_econ_board_consents_pol_econ_board_account_id_cate_8936f41f")
  @@index([pol_econ_board_admin_id])
  @@index([pol_econ_board_account_id, created_at], map: "pol_econ_board_consents_pol_econ_board_account_id_crea_2b28527c")
  @@index([source(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Immutable consent change history (snapshot log). Each entry records an
/// action on a consent, including actor context and evidence. Supports
/// auditability and regulatory proof of consent lifecycle. Relates to {@link
/// pol_econ_board_consents} and {@link pol_econ_board_accounts}.
///
/// @namespace Compliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_econ_board_consent_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Target consent's {@link pol_econ_board_consents.id}
  pol_econ_board_consent_id String @db.Uuid

  /// Subject account's {@link pol_econ_board_accounts.id} for whom the consent
  /// applies.
  pol_econ_board_account_id String @db.Uuid

  /// Acting admin's {@link pol_econ_board_admins.id} when a staff member
  /// performed the action.
  pol_econ_board_admin_id String? @db.Uuid

  /// Action taken: grant, revoke, update. Textual classifier for business
  /// interpretation.
  action String

  /// Optional reason or note explaining the action context.
  reason String?

  /// Evidence reference supporting this action (if any).
  evidence_uri String? @db.VarChar(80000)

  /// Role of the actor performing the action (member, admin, system).
  actor_role String?

  /// When the consent action occurred.
  occurred_at DateTime @db.Timestamptz

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Record last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for redaction workflows (rare).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  consent pol_econ_board_consents @relation(fields: [pol_econ_board_consent_id], references: [id], onDelete: Cascade)
  account pol_econ_board_accounts @relation(fields: [pol_econ_board_account_id], references: [id], onDelete: Cascade)
  admin   pol_econ_board_admins?  @relation(fields: [pol_econ_board_admin_id], references: [id], onDelete: Cascade)

  @@index([pol_econ_board_admin_id])
  @@index([pol_econ_board_consent_id, occurred_at], map: "pol_econ_board_consent_logs_pol_econ_board_consent_id__73b4ea38")
  @@index([pol_econ_board_account_id, occurred_at], map: "pol_econ_board_consent_logs_pol_econ_board_account_id__7cc5e335")
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Registry of personal data processing activities for compliance. Stores
/// human-readable codes, purposes, categories of data and recipients, lawful
/// bases, retention guidance, and approval flags. Used for audits, DPIA
/// references, and privacy notices.
///
/// @namespace Compliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_econ_board_processing_activities {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Stable unique business code for the processing activity.
  code String

  /// Short name/title of the processing activity.
  name String

  /// Business purpose description for this processing activity.
  purpose String

  /// Categories of personal data processed (free-text taxonomy).
  data_categories String

  /// Categories of data recipients/processors (free-text taxonomy).
  recipient_categories String

  /// Primary legal basis (e.g., contract, consent, legitimate_interest,
  /// legal_obligation).
  lawful_basis String

  /// Retention policy summary (e.g., '90 days logs; 2 years moderation
