  //----
  // RELATIONS
  //----
  @@unique([code])
  @@index([lawful_basis, created_at], map: "pol_econ_board_processing_activities_lawful_basis_crea_8c3443bb")
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([purpose(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Canonical Data Subject Access Request (DSAR) cases. Tracks requester
/// account, type (access, deletion, portability, rectification, restriction,
/// objection), verification status, lifecycle status, due dates, and a
/// unique tracking code. Event history captured in {@link
/// pol_econ_board_dsar_events}.
///
/// @namespace Compliance
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_econ_board_dsar_requests {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Requester account's {@link pol_econ_board_accounts.id}
  pol_econ_board_account_id String @db.Uuid

  /// Assigned moderator's {@link pol_econ_board_moderators.id} handling the
  /// case (optional).
  pol_econ_board_moderator_id String? @db.Uuid

  /// Approving admin's {@link pol_econ_board_admins.id} for
  /// escalations/closures (optional).
  pol_econ_board_admin_id String? @db.Uuid

  /// DSAR type: access, deletion, portability, rectification, restriction,
  /// objection (business-controlled).
  type String

  /// Case status (e.g., received, verifying, in_progress, extended, fulfilled,
  /// denied, closed).
  status String

  /// Identity verification status (e.g., pending, success, failed).
  verification_status String

  /// When the request was submitted.
  submitted_at DateTime @db.Timestamptz

  /// Primary due date based on regulatory SLA.
  due_at DateTime @db.Timestamptz

  /// Extended due date if obtained under lawful conditions.
  extended_until DateTime? @db.Timestamptz

  /// Externally-shareable tracking code for the request.
  tracking_code String

  /// Intake channel (e.g., in_app, email).
  channel String

  /// Business priority score for triage (higher = more urgent).
  priority Int @db.Integer

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Record last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp (if redacted).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  requester          pol_econ_board_accounts    @relation(fields: [pol_econ_board_account_id], references: [id], onDelete: Cascade)
  assignee_moderator pol_econ_board_moderators? @relation(fields: [pol_econ_board_moderator_id], references: [id], onDelete: Cascade)
  approver_admin     pol_econ_board_admins?     @relation(fields: [pol_econ_board_admin_id], references: [id], onDelete: Cascade)

  pol_econ_board_dsar_events      pol_econ_board_dsar_events[]
  pol_econ_board_data_export_jobs pol_econ_board_data_export_jobs[]

  @@unique([tracking_code])
  @@index([pol_econ_board_moderator_id])
  @@index([pol_econ_board_admin_id])
  @@index([pol_econ_board_account_id, submitted_at], map: "pol_econ_board_dsar_requests_pol_econ_board_account_id_598a5033")
  @@index([status, due_at])
  @@index([status(ops: raw("gin_trgm_ops"))], type: Gin)
}

